import React, { useState, useEffect } from 'react';

const ReportsViewer = () => {
  const [reports, setReports] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedReport, setSelectedReport] = useState(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [mountedPartitions, setMountedPartitions] = useState([]);
  const [formData, setFormData] = useState({
    reportType: 'mbr',
    partitionId: '',
    filePath: '',
  });

  // Cargar reportes existentes
  useEffect(() => {
    fetchReports();
    fetchMountedPartitions();
  }, []);

  const fetchReports = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8080/reports/');
      if (!response.ok) {
        throw new Error(`Error: ${response.status}`);
      }
      const data = await response.json();
      setReports(data.reports || {});
    } catch (err) {
      setError('Error cargando reportes: ' + err.message);
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchMountedPartitions = async () => {
    try {
      const response = await fetch('http://localhost:8080/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ commands: 'mounted' }),
      });

      if (!response.ok) {
        throw new Error(`Error: ${response.status}`);
      }

      const data = await response.json();

      // Extraer IDs de particiones montadas del resultado de texto
      // Esto es un analizador simple, se puede mejorar
      const outputLines = data.output.split('\n');
      const mountedIdsLine = outputLines.find(line => line.startsWith('IDs montados:'));

      if (mountedIdsLine) {
        const ids = mountedIdsLine
          .replace('IDs montados:', '')
          .split(',')
          .map(id => id.trim())
          .filter(id => id);

        setMountedPartitions(ids);
      }
    } catch (err) {
      console.error('Error obteniendo particiones montadas:', err);
      // No establecer error aquí para no bloquear el componente
    }
  };

  const handleViewReport = (report) => {
    setSelectedReport(report);
  };

  const handleCloseViewer = () => {
    setSelectedReport(null);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const generateReport = async (e) => {
    e.preventDefault();

    const { reportType, partitionId, filePath } = formData;

    if (!reportType || !partitionId) {
      alert('Tipo de reporte y ID de partición son obligatorios');
      return;
    }

    const needsFilePath = ['file', 'ls'].includes(reportType);
    if (needsFilePath && !filePath) {
      alert('Para los reportes file y ls se requiere especificar una ruta de archivo');
      return;
    }

    try {
      setIsGenerating(true);

      // Construir el comando rep
      let command = `rep -name=${reportType} -id=${partitionId}`;

      // Generar nombre automático en carpeta reportes
      const timestamp = new Date().toISOString().replace(/[:.]/g, '_');
      const reportPath = `${reportType}_${partitionId}_${timestamp}.png`;
      command += ` -path=${reportPath}`;

      if (needsFilePath) {
        command += ` -path_file_ls=${filePath}`;
      }

      const response = await fetch('http://localhost:8080/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ commands: command }),
      });

      if (!response.ok) {
        throw new Error(`Error del servidor: ${response.status}`);
      }

      const result = await response.json();

      if (result.error) {
        throw new Error(result.error);
      }

      // Esperar 1 segundo para asegurar que el archivo está disponible
      setTimeout(() => {
        fetchReports();
        setIsGenerating(false);
      }, 1000);

    } catch (err) {
      setError('Error generando reporte: ' + err.message);
      setIsGenerating(false);
    }
  };

  const renderReportTypeSelector = () => (
    <select 
      name="reportType" 
      value={formData.reportType} 
      onChange={handleInputChange}
      className="report-selector"
    >
      <option value="mbr">MBR - Master Boot Record</option>
      <option value="disk">DISK - Visualización del Disco</option>
      <option value="inode">INODE - Tabla de Inodos</option>
      <option value="block">BLOCK - Bloques</option>
      <option value="bm_inode">BM_INODE - Bitmap de Inodos</option>
      <option value="bm_block">BM_BLOCK - Bitmap de Bloques</option>
      <option value="tree">TREE - Árbol de Directorios</option>
      <option value="sb">SB - Superbloque</option>
      <option value="file">FILE - Contenido de Archivo</option>
      <option value="ls">LS - Listado de Directorio</option>
    </select>
  );

  return (
    <div className="reports-container">
      <h2>Visor de Reportes</h2>

      {/* Formulario para generar reportes */}
      <div className="report-generator">
        <h3>Generar Reporte</h3>
        <form onSubmit={generateReport}>
          <div className="form-group">
            <label>Tipo de Reporte:</label>
            {renderReportTypeSelector()}
          </div>

          <div className="form-group">
            <label>ID de Partición:</label>
            <select 
              name="partitionId" 
              value={formData.partitionId} 
              onChange={handleInputChange}
              className="partition-selector"
              required
            >
              <option value="">-- Seleccionar Partición --</option>
              {mountedPartitions.map(id => (
                <option key={id} value={id}>{id}</option>
              ))}
            </select>
          </div>

          {['file', 'ls'].includes(formData.reportType) && (
            <div className="form-group">
              <label>Ruta de Archivo/Carpeta:</label>
              <input 
                type="text" 
                name="filePath" 
                value={formData.filePath}
                onChange={handleInputChange}
                placeholder="/ruta/al/archivo"
                required
              />
            </div>
          )}

          <button 
            type="submit" 
            className="btn-primary"
            disabled={isGenerating}
          >
            {isGenerating ? 'Generando...' : 'Generar Reporte'}
          </button>
        </form>
      </div>

      {/* Visualizador de reportes */}
      {loading ? (
        <div className="loading">Cargando reportes disponibles...</div>
      ) : error ? (
        <div className="error-message">{error}</div>
      ) : (
        <div className="reports-list">
          {Object.keys(reports).length === 0 ? (
            <p>No hay reportes disponibles. Genere uno usando el formulario de arriba.</p>
          ) : (
            <>
              {Object.entries(reports).map(([type, typeReports]) => (
                <div key={type} className="report-category">
                  <h3>{type.toUpperCase()} Reports ({typeReports.length})</h3>
                  <div className="report-grid">
                    {typeReports.map((report, index) => (
                      <div key={index} className="report-card" onClick={() => handleViewReport(report)}>
                        <div className="report-thumbnail">
                          <img 
                            src={`http://localhost:8080${report.url}`}
                            alt={report.name}
                            className="thumbnail"
                          />
                        </div>
                        <div className="report-info">
                          <div className="report-name">{report.name}</div>
                          <div className="report-date">{report.created}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      )}

      {/* Modal para ver reporte completo */}
      {selectedReport && (
        <div className="report-modal-backdrop" onClick={handleCloseViewer}>
          <div className="report-modal-content" onClick={e => e.stopPropagation()}>
            <div className="report-modal-header">
              <h3>{selectedReport.name}</h3>
              <button className="modal-close" onClick={handleCloseViewer}>×</button>
            </div>
            <div className="report-modal-body">
              <img 
                src={`http://localhost:8080${selectedReport.url}`}
                alt={selectedReport.name}
                className="full-report-image"
              />
            </div>
            <div className="report-modal-footer">
              <p>Generado: {selectedReport.created}</p>
              <a 
                href={`http://localhost:8080${selectedReport.url}`}
                download={selectedReport.name}
                className="download-link"
              >
                Descargar Imagen
              </a>
              <a 
                href={`http://localhost:8080/reports/${selectedReport.name.replace(/\.[^.]+$/, '.dot')}`}
                download={selectedReport.name.replace(/\.[^.]+$/, '.dot')}
                className="download-link dot-link"
              >
                Descargar DOT
              </a>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReportsViewer;
